/** @jsxImportSource kerfjs */
import { delegate } from 'kerfjs';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import '@awesome.me/webawesome/dist/components/button/button.js';
import './command-palette.css';

// The supplied Kerf/Web Awesome catalog has no CommandPalette export or recipe.
// DialogHeader and EmptyState match parts of the need. Select is a value field,
// MenuItem is navigation, and Dropdown is an anchored menu, so none supplies
// searchable, grouped commands plus recent history. This is an app composition.
export interface Command { id: string; label: string; group: string; keywords?: string; disabled?: boolean; }
interface DialogElement extends HTMLElement { open: boolean; }
export interface CommandPolicy {
  commands: Command[];
  loadRecent(): string[];
  saveRecent(ids: string[]): void;
  dispatch(commandId: string): void;
}
export function createCommandPalette(id: string, policy: CommandPolicy) {
  let query = '';
  let open = false;
  let invoker: HTMLElement | null = null;
  let recent = [...new Set(policy.loadRecent())].filter(key => policy.commands.some(command => command.id === key)).slice(0, 8);
  function groups() {
    const needle = query.trim().toLocaleLowerCase();
    const matches = policy.commands.filter(command => (command.label + ' ' + (command.keywords ?? '')).toLocaleLowerCase().includes(needle));
    const result: { label: string; commands: Command[] }[] = [];
    const recentCommands = needle ? [] : recent.flatMap(key => matches.filter(command => command.id === key));
    if (recentCommands.length) result.push({ label: 'Recent commands', commands: recentCommands });
    for (const command of matches) {
      if (recentCommands.includes(command)) continue;
      let group = result.find(group => group.label === command.group && group.label !== 'Recent commands');
      if (!group) { group = { label: command.group, commands: [] }; result.push(group); }
      group.commands.push(command);
    }
    return result;
  }
  const render = () => {
    const sections = groups();
    const count = sections.reduce((count, section) => count + section.commands.length, 0);
    return <section class="command-composition kui-layout">
      <wa-button data-action="commands.show">Open command palette</wa-button>
      <wa-dialog id={id} class="command-dialog" open={open} without-header label="Command palette"
        aria-labelledby={id + '-title'} aria-describedby={id + '-summary'}>
        <DialogHeader title="Command palette" titleId={id + '-title'}
          summary="Search commands, then choose one to run." summaryId={id + '-summary'}
          actions={<wa-button appearance="plain" data-action="commands.close">Close</wa-button>} />
        <div class="kui-dialog-body kui-section-stack">
          <div class="command-search">
            <label for={id + '-query'}>Find a command</label>
            <input id={id + '-query'} type="search" data-command-query value={query}
              aria-describedby={id + '-keys'} aria-controls={id + '-results'} autocomplete="off" />
            <p id={id + '-keys'}>Tab through commands, or use Up and Down to move. Enter runs a command. Escape closes the palette.</p>
          </div>
          <p role="status" aria-live="polite">{count} commands found.</p>
          <div id={id + '-results'} class="kui-section-stack">
            {count ? sections.map((section, index) => <section aria-labelledby={id + '-group-' + index}>
              <h3 id={id + '-group-' + index}>{section.label}</h3>
              <ul class="command-list">{section.commands.map(command => <li>
                <button class="command-result" type="button" data-action="commands.run" data-command-id={command.id} disabled={command.disabled}>
                  {command.label}{command.disabled && <span> — Unavailable</span>}
                </button>
              </li>)}</ul>
            </section>) : <EmptyState title="No matching commands" detail="Try a different search."
              action={<wa-button data-action="commands.clear">Clear search</wa-button>} />}
          </div>
        </div>
      </wa-dialog>
    </section>;
  };
  function connect(root: HTMLElement, invalidate: () => void) {
    const dialog = () => root.querySelector<DialogElement>('#' + CSS.escape(id));
    const search = () => root.querySelector<HTMLInputElement>('[data-command-query]');
    const enabled = () => Array.from(root.querySelectorAll<HTMLButtonElement>('[data-action="commands.run"]:not(:disabled)'));
    const actions = delegate(root, 'click', '[data-action]', (_event, element) => {
      const action = element.getAttribute('data-action');
      if (action === 'commands.show') {
        invoker = element as HTMLElement;
        query = ''; open = true;
        invalidate();
        const modal = dialog();
        if (modal) modal.open = true;
      } else if (action === 'commands.close') {
        const modal = dialog(); if (modal) modal.open = false;
      } else if (action === 'commands.clear') { query = ''; invalidate(); search()?.focus(); }
      else if (action === 'commands.run') {
        const commandId = element.getAttribute('data-command-id');
        const command = policy.commands.find(command => command.id === commandId);
        if (!command || command.disabled) return;
        recent = [command.id, ...recent.filter(key => key !== command.id)].slice(0, 8);
        policy.saveRecent(recent);
        const modal = dialog(); if (modal) modal.open = false;
        policy.dispatch(command.id);
      }
    });
    const input = delegate(root, 'input', '[data-command-query]', (_event, element) => {
      const field = element as HTMLInputElement;
      query = field.value;
      invalidate();
      search()?.focus(); // Morphing should preserve this native input and its caret.
    });
    const keys = delegate(root, 'keydown', '[data-command-query], [data-action="commands.run"]', (event, element) => {
      const key = event as KeyboardEvent;
      if (key.isComposing) return;
      const buttons = enabled();
      const index = buttons.indexOf(element as HTMLButtonElement);
      if (key.key === 'ArrowDown' || key.key === 'ArrowUp') {
        key.preventDefault();
        if (!buttons.length) return;
        const next = index < 0 ? (key.key === 'ArrowDown' ? 0 : buttons.length - 1)
          : (index + (key.key === 'ArrowDown' ? 1 : -1) + buttons.length) % buttons.length;
        buttons[next].focus();
        buttons[next].scrollIntoView({ block: 'nearest' });
      } else if (index >= 0 && (key.key === 'Home' || key.key === 'End')) {
        key.preventDefault(); buttons[key.key === 'Home' ? 0 : buttons.length - 1]?.focus();
      } else if (index < 0 && key.key === 'Enter') {
        key.preventDefault(); buttons[0]?.click();
      }
      // Native button Enter/Space activation and modal Escape are preserved.
    });
    const afterShow = (event: Event) => { if (event.target === dialog()) search()?.focus(); };
    const afterHide = (event: Event) => {
      if (event.target !== dialog()) return;
      open = false;
      invalidate();
      if (invoker?.isConnected) invoker.focus();
    };
    root.addEventListener('wa-after-show', afterShow);
    root.addEventListener('wa-after-hide', afterHide);
    return () => {
      actions(); input(); keys();
      root.removeEventListener('wa-after-show', afterShow);
      root.removeEventListener('wa-after-hide', afterHide);
    };
  }
  return { render, connect };
}

