.command-composition { color:var(--kui-color-text); }
.command-dialog { --spacing:0; --width:min(42rem, calc(100vw - 2 * var(--kui-layout-dialog-inset))); }
/* Web Awesome owns modal focus, dismissal, and the sole body scroll boundary. */
.command-search { display:grid; gap:var(--kui-layout-control-gap); }
.command-search input { width:100%; box-sizing:border-box; min-width:0; min-height:2.75rem; padding:var(--kui-space-xs) var(--kui-space-s); font:inherit; color:var(--kui-color-text); background:var(--kui-color-surface); border:1px solid var(--kui-color-border); border-radius:var(--kui-radius-m); }
.command-composition p { margin:0; color:var(--kui-color-text-quiet); }
.command-composition h3 { margin:0 0 var(--kui-space-xs); font-size:var(--kui-font-s); }
.command-list { list-style:none; margin:0; padding:0; display:grid; gap:var(--kui-layout-control-gap); }
.command-result { width:100%; text-align:start; min-height:2.75rem; padding:var(--kui-space-s); font:inherit; overflow-wrap:anywhere; border:1px solid var(--kui-color-border); border-radius:var(--kui-radius-m); background:var(--kui-color-surface); color:var(--kui-color-text); }
.command-result:hover:not(:disabled) { background:var(--kui-color-neutral-fill-quiet); }
.command-composition :focus-visible { outline:var(--kui-focus-ring); outline-offset:2px; }
